  "  function capsule(p,c){var labels={wide:'W',slow:'S',multi:'M',life:'+',shield:'◆',fire:'F',laser:'L',score:'×2'},x=c.x*W,y=c.y*H;ctx.save();ctx.shadowColor=p.paddle;ctx.shadowBlur=12;ctx.fillStyle=p.bg2;ctx.strokeStyle=p.paddle;ctx.lineWidth=2;roundRect(x-13,y-10,26,20,7);ctx.fill();ctx.stroke();ctx.fillStyle=p.ball;ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(labels[c.type]||'?',x,y);ctx.restore();}",
  "  function stateOf(view){return view&&view.state||view||{};}",
  "  function render(view){if(!view)return;lastView=view;var s=stateOf(view),p=palettes[themeName];background(p);var mask=typeof s.bricks==='number'?s.bricks:0,dam=typeof s.damaged==='number'?s.damaged:0,dam2=typeof s.damaged2==='number'?s.damaged2:0,dur=s.durability||[3,2,1,1];for(var r=0;r<ROWS;r++)for(var c=0;c<COLS;c++){var bit=1<<(r*COLS+c);if(mask&bit)brick(p,r,c,(dam2&bit)?2:((dam&bit)?1:0),dur[r]);}var balls=s.balls||[s.ball||{x:.5,y:.5}];for(var b=0;b<balls.length;b++)ball(p,balls[b],b,s.fireLeft>0);paddle(p,typeof s.px==='number'?s.px:.5,s.paddleHalf||.09,s.wideLeft>0);for(var q=0;q<(s.capsules||[]).length;q++)capsule(p,s.capsules[q]);if(s.shield>0){ctx.save();ctx.strokeStyle=p.paddle;ctx.shadowColor=p.paddle;ctx.shadowBlur=18;ctx.lineWidth=4;ctx.globalAlpha=.8;ctx.beginPath();ctx.moveTo(20,H-18);ctx.lineTo(W-20,H-18);ctx.stroke();ctx.restore();}if(s.laserLeft>0){ctx.save();ctx.strokeStyle='#ff4df0';ctx.shadowColor='#ff4df0';ctx.shadowBlur=18;ctx.lineWidth=2;ctx.globalAlpha=.75;ctx.beginPath();ctx.moveTo((s.px||.5)*W,PY*H-12);ctx.lineTo((s.px||.5)*W,FT*H);ctx.stroke();ctx.restore();}scoreEl.textContent=(s.score||0)+' pts';levelEl.textContent='Level '+(s.level||1)+'/'+(s.levels||6)+(s.levelName?' · '+s.levelName:'');livesEl.textContent=new Array((s.lives||0)+1).join('●');comboEl.style.display=s.combo>1?'inline-block':'none';comboEl.textContent='Combo ×'+Math.min(4,1+Math.floor(((s.combo||1)-1)/4));powerEl.innerHTML=(s.wideLeft>0?'<span>WIDE '+Math.ceil(s.wideLeft/1000)+'s</span>':'')+(s.slowLeft>0?'<span>SLOW '+Math.ceil(s.slowLeft/1000)+'s</span>':'')+(s.shield>0?'<span>SHIELD ×'+s.shield+'</span>':'')+(s.fireLeft>0?'<span>FIRE '+Math.ceil(s.fireLeft/1000)+'s</span>':'')+(s.laserLeft>0?'<span>LASER '+Math.ceil(s.laserLeft/1000)+'s</span>':'')+(s.scoreBoostLeft>0?'<span>SCORE ×2 '+Math.ceil(s.scoreBoostLeft/1000)+'s</span>':'');lobby.style.display=s.started===false?'flex':'none';tools.style.display=s.started&&!s.over?'flex':'none';document.getElementById('pause').textContent=s.paused?'Resume':'Pause';if(s.paused&&!s.over){overlay.style.display='flex';document.getElementById('over-title').textContent='Paused';document.getElementById('over-body').textContent='Press P to continue';}else if(!s.over)overlay.style.display='none';if(lastMask!==null&&mask!==lastMask)tone(350+((s.combo||0)%6)*55,.055);lastMask=mask;requestAnimationFrame(reportSize);}",
  "  function select(group,value){var list=document.querySelectorAll('#'+group+' [data-v]');for(var i=0;i<list.length;i++)list[i].classList.toggle('sel',list[i].getAttribute('data-v')===value);}",
  "  document.getElementById('themes').onclick=function(e){var v=e.target.getAttribute('data-v');if(!v)return;themeName=v;root.setAttribute('data-theme',v);select('themes',v);if(lastView)render(lastView);};",
